import{_ as c,r as s,o as p,c as r,e as n,a as t,s as e}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"列表列 - October CMS - 3.x","titleTemplate":false,"description":"了解如何在列表结构中定义列。","frontmatter":{"subtitle":"了解如何在列表结构中定义列。"},"headers":[{"level":2,"title":"可用列","slug":"可用列","link":"#可用列","children":[]},{"level":2,"title":"列属性","slug":"列属性","link":"#列属性","children":[{"level":3,"title":"自定义值选择","slug":"自定义值选择","link":"#自定义值选择","children":[]},{"level":3,"title":"嵌套列选择","slug":"嵌套列选择","link":"#嵌套列选择","children":[]},{"level":3,"title":"直接 SQL 选择","slug":"直接-sql-选择","link":"#直接-sql-选择","children":[]},{"level":3,"title":"关联列选择","slug":"关联列选择","link":"#关联列选择","children":[]},{"level":3,"title":"工具提示","slug":"工具提示","link":"#工具提示","children":[]}]}],"relativePath":"3.x/zh-cn/element/list-columns.md","filePath":"3.x/zh-cn/element/list-columns.md"}'),d={name:"3.x/zh-cn/element/list-columns.md"};function u(i,a,k,m,g,h){const l=s("pre-heading"),o=s("post-heading");return p(),r("div",null,[n(l),a[0]||(a[0]=t("h1",null,"列表列",-1)),n(o),a[1]||(a[1]=e(`<p>列表列是列表使用的列定义。它们在以下区域中使用。</p><ul><li><a href="./../extend/lists/list-controller.html">后端列表控制器</a></li><li><a href="./../extend/forms/relation-controller.html">后端关联控制器</a></li></ul><p>所有列表列都通过各自的 <strong>type</strong> 属性来标识。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">columns</span><span class="token punctuation">:</span>
    <span class="token key atrule">mycolumn</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> number
        <span class="token comment"># ...</span>
</code></pre></div><h2 id="可用列"><a href="#可用列" class="header-anchor">#</a> 可用列</h2><p>以下列表列可用：</p>`,6)),a[2]||(a[2]=t("div",{class:"content-list-p",markdown:"1"},[t("p",null,[t("a",{href:"./lists/column-text.html"},"Text"),t("a",{href:"./lists/column-number.html"},"Number"),t("a",{href:"./lists/column-image.html"},"Image"),t("a",{href:"./lists/column-switch.html"},"Switch"),t("a",{href:"./lists/column-summary.html"},"Summary"),t("a",{href:"./lists/column-datetime.html"},"Date & Time"),t("a",{href:"./lists/column-selectable.html"},"Selectable"),t("a",{href:"./lists/column-linkage.html"},"Linkage"),t("a",{href:"./lists/column-partial.html"},"Partial"),t("a",{href:"./lists/column-colorpicker.html"},"Color Picker"),t("a",{href:"./lists/column-currency.html"},"Currency")])],-1)),a[3]||(a[3]=e(`<h2 id="列属性"><a href="#列属性" class="header-anchor">#</a> 列属性</h2><p>对于每个列，您可以指定以下属性（如适用）：</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>向用户显示列表列时使用的名称。</td></tr><tr><td><strong>type</strong></td><td>定义此列的渲染方式。</td></tr><tr><td><strong>default</strong></td><td>当值为空时，指定列的默认值。</td></tr><tr><td><strong>searchable</strong></td><td>将此列包含在列表搜索结果中。默认值：<code>false</code>。</td></tr><tr><td><strong>invisible</strong></td><td>指定此列是否默认隐藏。默认值：<code>false</code>。</td></tr><tr><td><strong>sortable</strong></td><td>指定此列是否可以排序。默认值：<code>true</code>。</td></tr><tr><td><strong>sortableDefault</strong></td><td>指定此列是否默认排序。这应仅在单个可排序列上使用。支持的值：<code>asc</code>、<code>desc</code>。</td></tr><tr><td><strong>clickable</strong></td><td>如果设置为 false，则在点击列时禁用默认的点击行为。默认值：true。</td></tr><tr><td><strong>select</strong></td><td>定义用于值的自定义 SQL select 语句。如果指定了 <code>relation</code>，则此项引用关联数据库表上的列。</td></tr><tr><td><strong>valueFrom</strong></td><td>定义用于源值的模型属性。如果指定了 <code>relation</code>，则此项引用关联的属性并预加载该关联。</td></tr><tr><td><strong>displayFrom</strong></td><td>定义用于显示值的模型属性。</td></tr><tr><td><strong>relation</strong></td><td>定义作为源的模型关联名称，与 <code>select</code> 或 <code>valueFrom</code> 一起使用。</td></tr><tr><td><strong>relationCount</strong></td><td>将关联记录的数量显示为列值。必须与 <code>relation</code> 选项一起使用。默认值：<code>false</code></td></tr><tr><td><strong>relationWith</strong></td><td>在列表查询中预加载指定的关联定义。有助于提高嵌套列选择的性能。</td></tr><tr><td><strong>cssClass</strong></td><td>为列容器分配 CSS 类。</td></tr><tr><td><strong>headCssClass</strong></td><td>为列标题容器分配 CSS 类。</td></tr><tr><td><strong>width</strong></td><td>设置列宽，可以用百分比（10%）或像素（50px）指定。可以有一个未指定宽度的列，它将拉伸以占用可用空间。</td></tr><tr><td><strong>align</strong></td><td>指定列对齐方式。可能的值为 <code>left</code>、<code>right</code> 和 <code>center</code>。</td></tr><tr><td><strong>permissions</strong></td><td>当前后端用户必须拥有的<a href="./../extend/backend/permissions.html">权限</a>才能使用该列。支持单个权限的字符串或权限数组（只需其中一个即可授予访问权限）。</td></tr><tr><td><strong>order</strong></td><td>确定显示顺序时的数值权重，默认值每列递增 100 点。</td></tr><tr><td><strong>after</strong></td><td>使用显示顺序（+1）将此列放置在另一个现有列名之后。</td></tr><tr><td><strong>before</strong></td><td>使用显示顺序（-1）将此列放置在另一个现有列名之前。</td></tr><tr><td><strong>tooltip</strong></td><td>在列标签后添加带有工具提示的图标。请参阅下面的更多详细设置。</td></tr></tbody></table></div><h3 id="自定义值选择"><a href="#自定义值选择" class="header-anchor">#</a> 自定义值选择</h3><p>可以更改每列的源值和显示值。如果要从另一列获取列值，请使用 <code>valueFrom</code> 选项。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">other_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Something Great
    <span class="token key atrule">valueFrom</span><span class="token punctuation">:</span> name
</code></pre></div><p>如果要保留源列值但显示来自模型属性的不同值，请使用 <code>displayFrom</code> 选项。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">status_code</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Status
    <span class="token key atrule">displayFrom</span><span class="token punctuation">:</span> status_label
</code></pre></div><p>这主要适用于使用<a href="./../extend/database/mutators.html">模型访问器</a>修改显示值的情况。当您想显示某个值但按不同的值进行排序和搜索时，这很有用。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getStatusLabelAttribute</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token function">title_case</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">status_code</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="嵌套列选择"><a href="#嵌套列选择" class="header-anchor">#</a> 嵌套列选择</h3><p>在某些情况下，从嵌套数据结构中检索列值是有意义的，例如<a href="./../extend/database/relations.html">模型关联</a>列或 <a href="./../extend/system/models.html">jsonable 数组</a>。以下示例将在 PHP 中分别查找 <code>$record-&gt;content-&gt;title</code> 或 <code>$record-&gt;content[&#39;title&#39;]</code> 的值。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code>content<span class="token punctuation">[</span>title<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">name</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">sortable</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div><p>这样做的唯一缺点是该列不能使用 searchable 或 sortable 选项。要使列可搜索，出于性能原因，我们建议使用<a href="./../extend/database/model.html">模型事件</a>将其值复制到本地数据库表。或者，您可以使用下面进一步描述的 <code>relation</code> 属性。</p><h3 id="直接-sql-选择"><a href="#直接-sql-选择" class="header-anchor">#</a> 直接 SQL 选择</h3><p><code>select</code> 属性允许您使用自定义 select 语句创建列。任何有效的 SQL SELECT 语句都可以在此使用。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">full_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Full Name
    <span class="token key atrule">select</span><span class="token punctuation">:</span> concat(first_name<span class="token punctuation">,</span> <span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> last_name)
</code></pre></div><h3 id="关联列选择"><a href="#关联列选择" class="header-anchor">#</a> 关联列选择</h3><p><code>relation</code> 属性允许您将关联列作为数据库查询的一部分显示，从而允许对该列进行搜索和排序。<code>relation</code> 设置为<a href="./../database/relations.html">模型关联</a>的名称。在下一个示例中，<strong>name</strong> 值将被转换为在关联模型中找到的 name 属性（例如：<code>$model-&gt;name</code>）。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">group_name</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Group
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> groups
    <span class="token key atrule">select</span><span class="token punctuation">:</span> name
</code></pre></div><p>要显示显示关联记录数量的列，请使用 <code>relationCount</code> 属性。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">users_count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Users
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">relation</span><span class="token punctuation">:</span> users
    <span class="token key atrule">relationCount</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><div class="custom-block warning"><p>注意不要将关联命名为与现有数据库列相同的名称。例如，使用名称 <code>group_id</code> 可能由于命名冲突而破坏 group 关联。</p></div><h3 id="工具提示"><a href="#工具提示" class="header-anchor">#</a> 工具提示</h3><p><code>tooltip</code> 属性通过在列标题中添加信息图标来增强列表列。将鼠标悬停在此图标上会显示工具提示，提供有关该列的额外上下文或详细信息。此功能有助于为用户提供指导或说明以理解列内容。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span> Number of users in the group
</code></pre></div><p>除了提供工具提示 <code>title</code> 外，您还可以指定 <code>icon</code>（<a href="./../element/available-icons.html">可用图标</a>）和工具提示的 <code>placement</code>（<code>right</code>、<code>bottom</code>、<code>left</code>，默认值为 <code>top</code>）。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">count</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Count
    <span class="token key atrule">type</span><span class="token punctuation">:</span> number
    <span class="token key atrule">tooltip</span><span class="token punctuation">:</span>
        <span class="token key atrule">title</span><span class="token punctuation">:</span> Number of users in the group
        <span class="token key atrule">placement</span><span class="token punctuation">:</span> bottom
        <span class="token key atrule">icon</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>users
</code></pre></div>`,28))])}const b=c(d,[["render",u]]);export{f as __pageData,b as default};
